// Call/import helpers for code generated by xlat/calls.py and
// for the import thunks generated by tools/ws7/recomp/thunks/gen_thunks.py.
#ifndef RC_CALL_H
#define RC_CALL_H
#include <stddef.h>
#include "rc.h"

// --- Calls through __stubs ---------------------------------------------------
//
//   SPILL_IMP(); I_<slot>(c); FILL_IMP();
//
// The call does not push a return address, so at the thunk the stack
// arguments are at guest rsp+0, +8, ... The thunk reads the SysV argument
// registers (rdi rsi rdx rcx r8 r9, xmm0..7, al for variadics) from rc_ctx
// and writes rax/rdx/xmm0/xmm1 back. Callee-saved guest registers stay in the
// caller's C locals (a native function preserves them).
#define SPILL_IMP() do { c->r[0] = rax; c->r[1] = rcx; c->r[2] = rdx; c->r[4] = rsp; c->r[6] = rsi; \
  c->r[7] = rdi; c->r[8] = r8; c->r[9] = r9; c->x[0] = x0; c->x[1] = x1; c->x[2] = x2; c->x[3] = x3; \
  c->x[4] = x4; c->x[5] = x5; c->x[6] = x6; c->x[7] = x7; } while (0)
#define FILL_IMP() do { rax = c->r[0]; rdx = c->r[2]; x0 = c->x[0]; x1 = c->x[1]; } while (0)

// --- Native call primitives (runtime/rc_native_arm64.S) ----------------------
// rc_native_call itself is declared in rc.h. The variants:
void rc_native_call_x8(uint64_t fn, const uint64_t ix[8], const uint64_t dx[8], uint64_t ret[4], uint64_t x8);
void rc_native_call_hfa(uint64_t fn, const uint64_t ix[8], const uint64_t dx[8], uint64_t ret[6]);
// The untyped bridge used by rc_icall_native and by the thunks of imports without a prototype.
void rc_native_generic(rc_ctx *c, uint64_t fn, unsigned stack_off);

// --- Argument cursor (x86-64 SysV) for generated thunks -----------------------
typedef struct rc_args {
  rc_ctx *c;
  uint32_t gi, fi;  // integer / SSE registers consumed so far
  uint64_t sp;      // next stack argument
} rc_args;

static inline void rc_args_init(rc_args *a, rc_ctx *c) {
  a->c = c; a->gi = 0; a->fi = 0; a->sp = c->r[4];
}
static inline uint64_t rc_arg_i(rc_args *a) {
  static const uint8_t order[6] = {7, 6, 2, 1, 8, 9};  // rdi rsi rdx rcx r8 r9
  if (a->gi < 6) return a->c->r[order[a->gi++]];
  uint64_t v = RC_LD(uint64_t, a->sp);
  a->sp += 8;
  return v;
}
// Low 64 bits of the next SSE argument (float in the low 32).
static inline uint64_t rc_arg_f(rc_args *a) {
  if (a->fi < 8) return a->c->x[a->fi++][0];
  uint64_t v = RC_LD(uint64_t, a->sp);
  a->sp += 8;
  return v;
}
// A whole 128-bit vector argument (__m128 and friends).
static inline rc_v128 rc_arg_v128(rc_args *a) {
  if (a->fi < 8) return a->c->x[a->fi++];
  a->sp = (a->sp + 15) & ~15ull;
  rc_v128 v = RC_LD(rc_v128, a->sp);
  a->sp += 16;
  return v;
}
// Aggregate classes for rc_arg_agg / rc_ret_agg: 0 = MEMORY, else
// RC_AGG(n eightbytes (1 or 2), eightbyte 0 is SSE, eightbyte 1 is SSE).
#define RC_AGG(n, sse0, sse1) ((n) | ((sse0) << 2) | ((sse1) << 3))
static inline void rc_arg_agg(rc_args *a, void *dst, uint32_t size, uint32_t align, uint32_t cls) {
  if (cls) {
    uint32_t n = cls & 3, nf = ((cls >> 2) & 1) + (n > 1 ? (cls >> 3) & 1 : 0), ni = n - nf;
    if (a->gi + ni <= 6 && a->fi + nf <= 8) {
      uint64_t w[2] = {0, 0};
      for (uint32_t k = 0; k < n; k++) w[k] = ((cls >> (2 + k)) & 1) ? rc_arg_f(a) : rc_arg_i(a);
      memcpy(dst, w, size);
      return;
    }
  }
  if (align < 8) align = 8;
  a->sp = (a->sp + align - 1) & ~(uint64_t)(align - 1);
  memcpy(dst, (const void *)(uintptr_t)a->sp, size);
  a->sp += (size + 7) & ~7u;
}
// Results.
static inline void rc_ret_f32(rc_ctx *c, float f) { c->x[0] = (rc_v128){rc_u32f(f), 0}; }
static inline void rc_ret_f64(rc_ctx *c, double d) { c->x[0] = (rc_v128){rc_u64f(d), 0}; }
static inline void rc_ret_v128(rc_ctx *c, rc_v128 v) { c->x[0] = v; }
static inline void rc_ret_agg(rc_ctx *c, const void *src, uint32_t size, uint32_t cls) {
  uint32_t n = cls & 3, gi = 0, fi = 0;
  uint64_t w[2] = {0, 0};
  memcpy(w, src, size);
  for (uint32_t k = 0; k < n; k++) {
    if ((cls >> (2 + k)) & 1) { c->x[fi] = (rc_v128){w[k], 0}; fi++; }
    else { c->r[gi ? 2 : 0] = w[k]; gi++; }
  }
}
// Cleanup of the typed thunks of imports that can run guest code (thunks/gen_thunks.py: UNWIND_GUARD):
// rc_unwind_end (rc_rt.h) unless no longjmp can have skipped a native->guest call (the newest one's
// frame is above this thunk's), the common case, which this decides inline.
void rc_unwind_end(rc_ctx **pc);
static inline void rc_unwind_guard(rc_ctx **pc) {
  if (__builtin_expect((uint64_t)pc > (*pc)->cg_fp, 0)) rc_unwind_end(pc);
}
static inline uint64_t rc_imp(uint64_t slot, const char *name) {
  uint64_t f = RC_LD(uint64_t, RC_A(slot));
  if (!f) rc_fail(name, slot);
  return f;
}

// --- Variadic arguments (runtime/rc_va.c) ----------------------------------------
// Darwin arm64 passes variadic arguments in consecutive 8-byte stack slots and a
// va_list is a pointer to them. These build such a slot array from a
// printf/scanf-style format and (a) the guest's remaining argument registers
// and stack (a variadic call), or (b) an x86-64 va_list struct
// {gp_offset, fp_offset, overflow_arg_area, reg_save_area}. `slots` needs
// rc_va_max(fmt) entries; the result is the arm64 va_list.
#define RC_VA_PRINTF 0
#define RC_VA_SCANF 1
#define RC_VA_NSLOG 2  // like printf, and fmt is an NSString/CFString: use rc_va_nsfmt first
size_t rc_va_max(const char *fmt);
void *rc_va_from_regs(rc_args *a, const char *fmt, int kind, uint64_t *slots);
void *rc_va_from_x86(const void *x86_va_list, const char *fmt, int kind, uint64_t *slots);
// UTF-8 contents of a CFString/NSString into buf (empty on failure).
const char *rc_va_nsfmt(uint64_t cfstring, char *buf, size_t cap);

// --- ObjC bridging (runtime/rc_objc.c) --------------------------------------------
// objc_msgSend_stret(sret, self, sel, ...) on x86 is objc_msgSend with the
// result in the memory at sret on arm64 (x8, or d0-d3 for homogeneous float
// aggregates).
void rc_objc_msgsend_stret(rc_ctx *c);
void rc_simd_invert_f4(rc_ctx *c);  // rc_native.c

// --- Import thunk table (generated thunks.c) -----------------------------------------
// Typed thunk of the import whose bound native address is `host`, or NULL.
rc_fn rc_import_thunk(uint64_t host);

#endif
